const raw = $input.first().json;
const payload = raw.body || raw;
const isEmpty = !payload || Object.keys(payload).length === 0;

// Manual test runs have no payload - use a sample task so the workflow is testable end to end
const sample = 'Research the three biggest trends in AI agent orchestration, then write a short LinkedIn post summarizing them.';
const task = (typeof payload.task === 'string' && payload.task.trim())
  ? payload.task.trim()
  : (isEmpty ? sample : '');

return [{
  json: {
    taskValid: !!task,
    validationError: task ? null : 'Request body must include a non-empty task string',
    taskId: payload.taskId || ('task-' + Date.now()),
    task,
    context: payload.context || '',
    requestedMaxSteps: Number(payload.maxSteps) || null,
    startedAt: new Date().toISOString(),
    history: [],
    stepCount: 0
  }
}];

const s = $input.first().json;
const maxSteps = Math.min(Number(s.requestedMaxSteps) || s.defaultMaxSteps, s.hardMaxSteps);

const roster = [
  '- researcher: gathers current facts, sources and background using web search',
  '- coder: writes, debugs and explains code, scripts, queries and technical designs',
  '- analyst: reasons over data, numbers, comparisons, trade-offs and strategy',
  '- writer: drafts polished text such as posts, emails, documents and summaries',
  '- reviewer: critiques a draft or result for errors, gaps and quality, and suggests fixes'
].join('\n');

const shape = JSON.stringify({
  reasoning: 'one or two sentences on why this route',
  route: 'researcher | coder | analyst | writer | reviewer | FINISH',
  instruction: 'specific instruction for the chosen specialist',
  confidence: 0
});

const system = [
  'You are the supervisor of a team of specialist AI agents. You never do the work yourself. You look at the task and the work completed so far, then decide which single specialist should act next, or FINISH if the task is fully answered.',
  'Specialists:\n' + roster,
  'Rules: choose exactly one route per turn. Give the specialist a concrete instruction that builds on earlier outputs. Never repeat a specialist with the same instruction. Prefer FINISH once the result is complete, or when a step has failed twice. Simple tasks may need only one specialist. Consider a reviewer step before FINISH for important written deliverables. You have used ' + s.stepCount + ' of ' + maxSteps + ' steps.',
  'Respond ONLY with valid JSON, no prose, matching exactly this shape: ' + shape
].join('\n\n');

const digest = (s.history || []).map(h =>
  'Step ' + h.step + ' [' + h.specialist + '] (' + h.status + '): ' + String(h.output).slice(0, 1200)
).join('\n\n') || 'No work done yet.';

const userMsg = 'Task: ' + s.task + (s.context ? '\nContext: ' + s.context : '') + '\n\nWork so far:\n' + digest;

return [{
  json: {
    ...s,
    maxSteps,
    supervisorRequest: {
      model: s.supervisorModel,
      max_tokens: 600,
      system,
      messages: [{ role: 'user', content: userMsg }]
    }
  }
}];

const state = $('Build Supervisor Request').first().json;
const resp = $input.first().json;
const { supervisorRequest, ...rest } = state;

const VALID = ['researcher', 'coder', 'analyst', 'writer', 'reviewer', 'FINISH'];
let d = null;
let parseError = null;
try {
  if (resp.error || !Array.isArray(resp.content)) {
    throw new Error(resp.error && resp.error.message ? resp.error.message : 'no content returned');
  }
  const raw = resp.content.filter(b => b.type === 'text').map(b => b.text).join('');
  d = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {
  parseError = e.message;
}

let route = d && VALID.includes(d.route) ? d.route : 'FINISH';
let reasoning = (d && d.reasoning) || (parseError ? 'Supervisor response could not be used: ' + parseError : 'No reasoning provided');
const instruction = (d && d.instruction) || '';
const history = state.history || [];
const last = history[history.length - 1];
let runStatus = 'running';

// Guardrails
if (parseError) {
  route = 'FINISH';
  runStatus = 'supervisor_error';
} else if (route !== 'FINISH' && state.stepCount >= state.maxSteps) {
  route = 'FINISH';
  runStatus = 'max_steps_reached';
  reasoning += ' (step limit reached)';
} else if (route !== 'FINISH' && last && last.specialist === route && last.instruction === instruction) {
  route = 'FINISH';
  runStatus = 'loop_detected';
  reasoning += ' (repeated route with identical instruction)';
}
if (route === 'FINISH' && runStatus === 'running') runStatus = 'completed';

const digest = history.map(h =>
  'Step ' + h.step + ' [' + h.specialist + ']: ' + String(h.output).slice(0, 2500)
).join('\n\n') || 'None yet.';

const specialistPrompt = 'Overall task: ' + state.task
  + (state.context ? '\nContext: ' + state.context : '')
  + '\n\nPrevious work:\n' + digest
  + '\n\nYour instruction: ' + instruction;

return [{
  json: {
    ...rest,
    route,
    currentInstruction: instruction,
    currentReasoning: reasoning,
    supervisorConfidence: d && typeof d.confidence === 'number' ? d.confidence : null,
    runStatus,
    specialistPrompt
  }
}];

const state = $('Parse Supervisor Decision').first().json;
const resp = $input.first().json;
const { specialistPrompt, ...rest } = state;

const text = Array.isArray(resp.content)
  ? resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim()
  : '';
const failed = !!resp.error || !text;
const errMsg = resp.error ? (resp.error.message || JSON.stringify(resp.error)) : 'empty response';

const entry = {
  step: (state.stepCount || 0) + 1,
  specialist: state.route,
  instruction: state.currentInstruction,
  supervisorReasoning: state.currentReasoning,
  status: failed ? 'failed' : 'ok',
  output: failed ? 'Specialist failed: ' + errMsg : text
};

return [{
  json: {
    ...rest,
    history: [...(state.history || []), entry],
    stepCount: entry.step
  }
}];

const s = $input.first().json;

const digest = (s.history || []).map(h =>
  'Step ' + h.step + ' [' + h.specialist + '] (' + h.status + '):\n' + String(h.output).slice(0, 4000)
).join('\n\n---\n\n') || 'No specialist work was performed.';

const system = 'You are the final editor of a multi-agent team. Using the completed work of the specialists, write the single best final answer to the original task. Be direct. Do not mention the internal routing or the specialists. Do not invent facts that are not supported by the work. If some steps failed, work with what is available and briefly note any gap.';

return [{
  json: {
    ...s,
    synthesisRequest: {
      model: s.supervisorModel,
      max_tokens: 2000,
      system,
      messages: [{ role: 'user', content: 'Original task: ' + s.task + (s.context ? '\nContext: ' + s.context : '') + '\n\nSpecialist work:\n' + digest }]
    }
  }
}];

const s = $('Build Synthesis Request').first().json;
const resp = $input.first().json;

let finalAnswer = Array.isArray(resp.content)
  ? resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n').trim()
  : '';

let status = s.runStatus;
if (!finalAnswer) {
  // Fall back to the last successful specialist output
  const lastOk = [...(s.history || [])].reverse().find(h => h.status === 'ok');
  finalAnswer = lastOk ? lastOk.output : 'No answer could be produced.';
  status = lastOk ? status + '_synthesis_fallback' : 'error';
}

const routingTrace = (s.history || []).map(h => ({
  step: h.step,
  specialist: h.specialist,
  instruction: h.instruction,
  supervisorReasoning: h.supervisorReasoning,
  status: h.status
}));

const durationMs = Date.now() - new Date(s.startedAt).getTime();

const whatsappText = '\uD83E\uDDED Agent Supervisor: task ' + s.taskId + ' ' + status
  + ' in ' + (s.history || []).length + ' step(s) [' + routingTrace.map(t => t.specialist).join(' > ') + ']\n\n'
  + finalAnswer.slice(0, 1500);

return [{
  json: {
    whatsappBusinessPhoneId: s.whatsappBusinessPhoneId,
    whatsappRecipientPhone: s.whatsappRecipientPhone,
    whatsappText,
    webhookResponse: {
      taskId: s.taskId,
      task: s.task,
      status,
      finalAnswer,
      stepsTaken: (s.history || []).length,
      routingTrace,
      durationMs
    }
  }
}];
